      "content": "{\n  \"name\": \"dsh-web-search-free\",\n  \"version\": \"1.9.1\",\n  \"description\": \"Free web search & fetch plugin for DeepSeek Harness (dsh) with multi-engine fallback (Tavily, Exa, Brave, Baidu, SearXNG and more)\",\n  \"icon\": \"./icon.svg\",\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"web-search\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/MochiNek0/dsh-web-search-free.git\"\n  },\n  \"homepage\": \"https://github.com/MochiNek0/dsh-web-search-free#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/MochiNek0/dsh-web-search-free/issues\"\n  },\n  \"engines\": {\n    \"dsh\": \">=0.1.2-rc.1\"\n  },\n  \"dsh\": {\n    \"name\": \"web-search-free\",\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-settings-plugins\"\n      ]\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"files\": [\n    \"dist\",\n    \"cordis.patch.yml\",\n    \"icon.svg\",\n    \"locale/*.json\"\n  ],\n  \"publishConfig\": {\n    \"registry\": \"https://registry.npmjs.org/\"\n  },\n  \"exports\": {\n    \".\": {\n      \"types\": \"./dist/index.d.ts\",\n      \"default\": \"./dist/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./dist/client.d.ts\",\n      \"default\": \"./dist/client.js\"\n    },\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"koishi\": {\n    \"description\": \"免费 Web Search 与内容抓取 (支持多引擎轮询 fallback)\"\n  },\n  \"main\": \"dist/index.js\",\n  \"types\": \"dist/index.d.ts\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"build\": \"node -e \\\"require('node:fs').rmSync('dist',{recursive:true,force:true})\\\" && tsc -p tsconfig.json && tsc -p tsconfig.client.json && node wrap-client.cjs\",\n    \"check\": \"node scripts/check-package.cjs\",\n    \"prepublishOnly\": \"pnpm run build && pnpm run check\"\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.3\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/schemastery\": \"^3.18.3\",\n    \"@types/node\": \"^18.0.0\",\n    \"@types/react\": \"^19.2.18\",\n    \"typescript\": \"^5.0.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    }\n  }\n}\n"
