flex\",\n              flexWrap: \"wrap\",\n              gap: 10,\n              alignItems: \"baseline\",\n            },\n          },\n          React.createElement(\n            \"span\",\n            {\n              style: {\n                fontWeight: 600,\n                fontSize: 13,\n                color: \"var(--dsw-alias-label-primary)\",\n              },\n            },\n            label,\n          ),\n          React.createElement(\n            \"span\",\n            {\n              style: {\n                fontFamily: \"ui-monospace, SFMono-Regular, Menlo, monospace\",\n              },\n            },\n            row.key ?? t(\"stats.keyless\"),\n          ),\n          row.benchedForMs > 0\n            ? React.createElement(\n                \"span\",\n                { style: { color: \"var(--dsw-alias-label-error)\" } },\n                t(\"stats.benched\", {\n                  min: Math.max(1, Math.ceil(row.benchedForMs / 60_000)),\n                }),\n              )\n            : null,\n        ),\n        React.createElement(\n          \"div\",\n          null,\n          `${t(\"stats.search\")}：${tallyText(row.search)}`,\n          row.fetch.calls > 0\n            ? `　${t(\"stats.fetch\")}：${tallyText(row.fetch)}`\n            : \"\",\n        ),\n        lastError\n          ? React.createElement(\n              \"div\",\n              {\n                style: {\n                  color: \"var(--dsw-alias-label-tertiary)\",\n                  wordBreak: \"break-word\",\n                },\n              },\n              t(\"stats.lastError\", { error: lastError }),\n            )\n          : null,\n      );\n    };\n    if (routesOk)\n      children.push(\n        React.createElement(\n          \"div\",\n          { style: { display: \"flex\", flexDirection: \"column\", gap: 10 } },\n          React.createElement(\n            \"div\",\n            { style: { display: \"flex\", alignItems: \"center\", gap: 8 } },\n            React.createElement(\n              \"button\",\n              {\n                type: \"button\",\n                onClick: () => {\n                  if (!statsOpen) void loadStats();\n                  setStatsOpen(!statsOpen);\n                },\n                style: {\n                  ...groupLabelStyle,\n                  appearance: \"none\",\n                  background: \"none\",\n                  border: 0,\n                  padding: 0,\n                  font: \"inherit\",\n                  fontSize: 11,\n                  fontWeight: 600,\n                  cursor: \"pointer\",\n                  textAlign: \"left\",\n                  display: \"flex\",\n                  alignItems: \"center\",\n                  gap: 4,\n                },\n              },\n              t(\"stats.label\"),\n              React.createElement(\n                \"span\",\n                {\n                  style: {\n                    display: \"inline-flex\",\n                    transition: \"transform .16s\",\n                    transform: statsOpen ? \"rotate(180deg)\" : \"none\",\n                  },\n                },\n                caret(11),\n              ),\n            ),\n            statsOpen\n              ? React.createElement(\n                  \"button\",\n                  {\n                    type: \"button\",\n                    disabled: statsLoading,\n                    onClick: () => void loadStats(),\n                    style: {\n                      ...btnOutlineStyle,\n                      fontSize: 11,\n                      padding: \"1px 8px\",\n                      marginLeft: \"auto\",\n                    },\n                  },\n                  t(statsLoading ? \"stats.loading\" : \"stats.refresh\"),\n                )\n              : null,\n          ),\n          statsOpen\n            ? React.createElement(\n                \"div\",\n                { style: { display: \"flex\", flexDirection: \"column\", gap: 8 } },\n                statsError\n                  ? React.createElement(\n                      \"div\",\n                      {\n                        style: {\n                          fontSize: 12,\n                          color: \"var(--dsw-alias-label-error)\",\n                        },\n                      },\n                      t(\"stats.error\", { error: statsError }),\n                    )\n                  : null,\n                stats\n                  ? React.createElement(\n                      \"div\",\n                      {\n                        style: {\n                          fontSize: 11,\n                          color: \"var(--dsw-alias-label-tertiary)\",\n                        },\n                      },\n                      t(\"stats.cache\", stats.cacheHits),\n                    )\n                  : null,\n                ...(stats && stats.rows.length === 0\n                  ? [\n                      React.createElement(\n                        \"div\",\n                        {\n                          key: \"empty\",\n                          style: {\n                            fontSize: 12,\n                            color: \"var(--dsw-alias-label-tertiary)\",\n                          },\n                        },\n                        t(\"stats.empty\"),\n                      ),\n                    ]\n                  : (stats?.rows ?? []).map(statsRow)),\n              )\n            : null,\n        ),\n      );\n    // Version and an on-demand update check. Needs the Host routes, and a\n    // Host new enough to report its version in the stats it already serves.\n    if (routesOk && stats?.version)\n      children.push(\n        React.createElement(\n          \"div\",\n          {\n            style: {\n              display: \"flex\",\n              alignItems: \"center\",\n              flexWrap: \"wrap\",\n              gap: 10,\n              fontSize: 12,\n              color: \"var(--dsw-alias-label-tertiary)\",\n            },\n          },\n          t(\"version.label\", { version: stats.version }),\n          React.createElement(\n            \"button\",\n            {\n              type: \"button\",\n              disabled: checkingUpdate,\n              onClick: () => void checkUpdate(),\n              style: {\n                ...btnOutlineStyle,\n                fontSize: 11,\n                padding: \"1px 8px\",\n                ...(checkingUpdate ? { opacity: 0.6, cursor: \"default\" } : {}),\n              },\n            },\n            t(checkingUpdate ? \"version.checking\" : \"version.check\"),\n          ),\n          update === null\n            ? null\n            : React.createElement(\n                \"span\",\n                {\n                  style:\n                    typeof update === \"string\"\n                      ? { color: \"var(--dsw-alias-label-error)\" }\n                      : update.updateAvailable\n                        ? { color: \"var(--dsw-alias-brand-primary)\" }\n                        : {},\n                },\n                typeof update === \"string\"\n                  ? update\n                  : update.updateAvailable\n                    ? t(\"version.available\", { latest: update.latest })\n                    : t(\"version.latest\"),\n              ),\n        ),\n      );\n    children.push(\n      React.createElement(\n        \"div\",\n        {\n          style: {\n            display: \"flex\",\n            alignItems: \"center\",\n            gap: 10,\n            justifyContent: \"flex-end\",\n            borderTop: \"1px solid var(--dsw-alias-border-l2)\",\n            paddingTop: 16,\n          },\n        },\n        // Left-aligned and outlined, away from 保存: this one is for uninstalling\n        // cleanly, not part of the edit/commit pair on the right.\n        React.createElement(\n          \"button\",\n          {\n            type: \"button\",\n            disabled: disabled || !configured,\n            onClick: () => (armed ? clearAll() : setArmed(true)),\n            title: t(\"clear.title\"),\n            style: {\n              ...btnOutlineStyle,\n              marginRight: \"auto\",\n              color: \"var(--dsw-alias-label-error)\",\n              ...(armed\n                ? {\n                    borderColor: \"var(--dsw-alias-label-error)\",\n                    fontWeight: 600,\n                  }\n                : {}),\n              ...(disabled || !configured\n                ? { opacity: 0.4, cursor: \"default\" }\n                : {}),\n            },\n          },\n          t(clearing ? \"clear.busy\" : armed ? \"clear.armed\" : \"clear.idle\"),\n        ),\n        failed === \"\"\n          ? null\n          : React.createElement(\n              \"span\",\n              {\n                style: {\n                  flex: 1,\n                  minWidth: 0,\n                  fontSize: 12,\n                  color: \"var(--dsw-alias-label-error)\",\n                },\n              },\n              failed,\n            ),\n        React.createElement(\n          \"button\",\n          {\n            type: \"button\",\n            disabled: disabled || !dirty,\n            onClick: () => {\n              setKeyDrafts({});\n              setOrderDraft(null);\n              setEnableFetchDraft(null);\n              setAdvDrafts({});\n              setArmed(false);\n              setFailed(\"\");\n            },\n            style: {\n              ...btnOutlineStyle,\n              ...(disabled || !dirty\n                ? { opacity: 0.4, cursor: \"default\" }\n                : {}),\n            },\n          },\n          t(\"action.discard\"),\n        ),\n        React.createElement(\n          \"button\",\n          {\n            type: \"button\",\n            disabled: disabled || !dirty,\n            onClick: save,\n            style: {\n              ...btnPrimaryStyle,\n              ...(disabled || !dirty\n                ? { opacity: 0.4, cursor: \"default\" }\n                : {}),\n            },\n          },\n          t(saving ? \"action.saving\" : \"action.save\"),\n        ),\n      ),\n    );\n    return children;\n  };\n\n  // Collapsed summary: how many engines are configured, surfaced on the\n  // header so the user can see at a glance whether the plugin is ready.\n  const summary =\n    configuredCount > 0\n      ? t(\"summary.configured\", { count: configuredCount })\n      : t(\"summary.none\");\n\n  // The one-liner the Plugins page places under the title it drew itself.\n  if (view === \"summary\") return text(t(\"header.subtitle\", { summary }));\n\n  // The page view: the surrounding page owns title, icon and crumb, so the\n  // card contributes only its form — no card shell, no disclosure of its own.\n  if (view === \"page\")\n    return React.createElement(\n      \"div\",\n      {\n        style: {\n          display: \"flex\",\n          flexDirection: \"column\",\n          gap: 24,\n        },\n      },\n      ...cardBody(),\n    );\n\n  return React.createElement(\n    \"li\",\n    {\n      style: {\n        listStyle: \"none\",\n        borderRadius: 12,\n        border: \"1px solid var(--dsw-alias-border-l2)\",\n        background: open\n          ? \"var(--dsw-alias-bg-layer-2)\"\n          : \"var(--dsw-alias-bg-layer-3)\",\n        transition: \"border-color .16s, background .16s\",\n      },\n    },\n    React.createElement(\n      \"button\",\n      {\n        type: \"button\",\n        onClick: () => setOpen(!open),\n        style: {\n          appearance: \"none\",\n          width: \"100%\",\n          font: \"inherit\",\n          textAlign: \"left\",\n          cursor: \"pointer\",\n          background: \"none\",\n          border: \"0\",\n          borderRadius: 12,\n          color: \"inherit\",\n          display: \"flex\",\n          alignItems: \"center\",\n          gap: 12,\n          padding: \"14px 16px\",\n        },\n      },\n      React.createElement(\n        \"div\",\n        {\n          style: {\n            display: \"flex\",\n            flexDirection: \"column\",\n            flex: 1,\n            gap: 2,\n            minWidth: 0,\n          },\n        },\n        React.createElement(\n          \"div\",\n          { style: { display: \"flex\", alignItems: \"center\", gap: 8 } },\n          React.createElement(\n            \"span\",\n            {\n              style: {\n                fontSize: 15,\n                fontWeight: 600,\n                color: \"var(--dsw-alias-label-primary)\",\n              },\n            },\n            t(\"header.title\"),\n          ),\n          dirty\n            ? React.createElement(\n                \"span\",\n                {\n                  style: {\n                    whiteSpace: \"nowrap\",\n                    background: \"var(--dsw-alias-bg-module-platform)\",\n                    color: \"var(--dsw-alias-label-secondary)\",\n                    borderRadius: 999,\n                    ...roundCorners,\n                    padding: \"1px 8px\",\n                    fontSize: 11,\n                    fontWeight: 500,\n                    lineHeight: \"17px\",\n                  },\n                },\n                t(\"header.unsaved\"),\n              )\n            : null,\n          configuredCount > 0\n            ? React.createElement(\n                \"span\",\n                {\n                  style: {\n                    whiteSpace: \"nowrap\",\n                    background: \"var(--dsw-alias-brand-primary)\",\n                    color: \"#fff\",\n                    borderRadius: 999,\n                    ...roundCorners,\n                    padding: \"1px 8px\",\n                    fontSize: 11,\n                    fontWeight: 500,\n                    lineHeight: \"17px\",\n                  },\n                },\n                t(\"header.engines\", { count: configuredCount }),\n              )\n            : null,\n        ),\n        React.createElement(\n          \"div\",\n          { style: { fontSize: 13, color: \"var(--dsw-alias-label-tertiary)\" } },\n          t(\"header.subtitle\", { summary }),\n        ),\n      ),\n      React.createElement(\n        \"span\",\n        {\n          style: {\n            color: \"var(--dsw-alias-label-tertiary)\",\n            display: \"inline-flex\",\n            flex: \"none\",\n            transition: \"transform .16s\",\n            transform: open ? \"rotate(180deg)\" : \"none\",\n          },\n        },\n        React.createElement(\n          \"svg\",\n          {\n            width: 14,\n            height: 14,\n            viewBox: \"0 0 14 14\",\n            fill: \"none\",\n            \"aria-hidden\": true,\n          },\n          React.createElement(\"path\", {\n            d: \"M3.5 5.5L7 9l3.5-3.5\",\n            stroke: \"currentColor\",\n            strokeWidth: 1.5,\n            strokeLinecap: \"round\",\n            strokeLinejoin: \"round\",\n          }),\n        ),\n      ),\n    ),\n    open\n      ? React.createElement(\n          \"div\",\n          {\n            style: {\n              display: \"flex\",\n              flexDirection: \"column\",\n              gap: 24,\n              margin: \"0 16px 16px\",\n              borderTop: \"1px solid var(--dsw-alias-border-l2)\",\n              paddingTop: 16,\n            },\n          },\n          ...cardBody(),\n        )\n      : null,\n  );\n}\n\n/**\n * dsh's theme applies `corner-shape: superellipse(1.5)` to `*`, so a\n * `border-radius` of 999px renders as a squircle instead of a pill, and 50% as\n * a squircle instead of a circle. Anything in this card that must be a TRUE\n * pill or circle opts back out, exactly as dsh's own pills do.\n */\nconst roundCorners = { cornerShape: \"round\" } as React.CSSProperties;\n\nconst inputStyle = {\n  height: 34,\n  padding: \"0 12px\",\n  font: \"inherit\",\n  fontSize: 13,\n  borderRadius: 8,\n  border: \"1px solid var(--dsw-alias-border-l2)\",\n  background: \"var(--dsw-alias-bg-layer-3)\",\n  color: \"var(--dsw-alias-label-primary)\",\n};\n\nconst btnOutlineStyle = {\n  font: \"inherit\",\n  fontSize: 13,\n  padding: \"5px 14px\",\n  borderRadius: 8,\n  cursor: \"pointer\",\n  border: \"1px solid var(--dsw-alias-border-l2)\",\n  background: \"none\",\n  color: \"var(--dsw-alias-label-secondary)\",\n};\n\nconst btnPrimaryStyle = {\n  font: \"inherit\",\n  fontSize: 13,\n  padding: \"5px 14px\",\n  borderRadius: 8,\n  cursor: \"pointer\",\n  border: \"1px solid transparent\",\n  background: \"var(--dsw-alias-label-primary)\",\n  color: \"var(--dsw-alias-bg-layer-3)\",\n};\n\nconst groupLabelStyle = {\n  fontSize: 11,\n  fontWeight: 600,\n  letterSpacing: \".2px\",\n  color: \"var(--dsw-alias-label-tertiary)\",\n};\n\n/** The on/off switch shared by every boolean in this card. */\nfunction toggleSwitch(on: boolean, disabled: boolean, onClick: () => void) {\n  return React.createElement(\n    \"button\",\n    {\n      type: \"button\",\n      role: \"switch\",\n      \"aria-checked\": on,\n      disabled,\n      onClick,\n      style: {\n        appearance: \"none\",\n        flex: \"none\",\n        width: 36,\n        height: 20,\n        borderRadius: 999,\n        ...roundCorners,\n        border: \"none\",\n        cursor: disabled ? \"default\" : \"pointer\",\n        padding: 0,\n        position: \"relative\",\n        background: on\n          ? \"var(--dsw-alias-brand-primary)\"\n          : \"var(--dsw-alias-bg-module-platform)\",\n        transition: \"background .16s\",\n      },\n    },\n    React.createElement(\"span\", {\n      style: {\n        position: \"absolute\",\n        top: 2,\n        left: on ? 18 : 2,\n        width: 16,\n        height: 16,\n        borderRadius: \"50%\",\n        ...roundCorners,\n        background: \"#fff\",\n        transition: \"left .16s\",\n        boxShadow: \"0 1px 3px rgba(0,0,0,.2)\",\n      },\n    }),\n  );\n}\n\n/** The single chevron used by every expander in this card. */\nfunction caret(size: number) {\n  return React.createElement(\n    \"svg\",\n    {\n      width: size,\n      height: size,\n      viewBox: \"0 0 14 14\",\n      fill: \"none\",\n      \"aria-hidden\": true,\n    },\n    React.createElement(\"path\", {\n      d: \"M3.5 5.5L7 9l3.5-3.5\",\n      stroke: \"currentColor\",\n      strokeWidth: 1.5,\n      strokeLinecap: \"round\",\n      strokeLinejoin: \"round\",\n    }),\n  );\n}\n\nfunction text(value: string) {\n  return React.createElement(\n    \"span\",\n    { style: { fontSize: 13, color: \"var(--dsw-alias-label-tertiary)\" } },\n    value,\n  );\n}\n"
