      "path": "src/providers/jina.ts",
      "content": "import { WebSearchProvider, SearchResult, FetchResult } from '../types.js';\nimport { ProviderError, assertOk, toSnippet, toPublishedAt } from './fields.js';\n\nexport const jinaProvider: WebSearchProvider = {\n  name: 'jina',\n  supportsFetch: true,\n\n  /**\n   * s.jina.ai returns ready-to-use markdown by default, which gave the model a\n   * wall of text with no structured `Sources:` list. Requesting JSON\n   * (`Accept: application/json`) instead returns one entry per result with\n   * `url`/`title`/`description`/`content`/`publishedTime`, which we project\n   * into structured sources so Jina behaves like the other providers.\n   */\n  async search(query: string, apiKey: string, signal?: AbortSignal): Promise<SearchResult> {\n    const res = await fetch(`https://s.jina.ai/${encodeURIComponent(query)}`, {\n      method: 'GET',\n      headers: {\n        'Authorization': `Bearer ${apiKey}`,\n        'Accept': 'application/json',\n      },\n      signal,\n    });\n    assertOk(res, 'Jina search');\n\n    // s.jina.ai JSON mode has shipped both as a bare array and wrapped as\n    // { code, status, data: [...] }; accept either so a future API revision\n    // does not silently empty the source list.\n    const data = await res.json();\n    const entries: any[] = Array.isArray(data)\n      ? data\n      : Array.isArray(data?.data)\n        ? data.data\n        : Array.isArray(data?.results)\n          ? data.results\n          : [];\n\n    const sources = entries\n      .map((entry: any) => {\n        const url = typeof entry?.url === 'string' ? entry.url : '';\n        if (!url) return undefined;\n        // `description` is the search engine's own excerpt; `content` is the\n        // whole crawled page, kept only as a fallback for entries without one.\n        const snippet = toSnippet(entry?.description) ?? toSnippet(entry?.content);\n        // `publishedTime` is what s.jina.ai returns today; the others are\n        // earlier API revisions' names for the same thing.\n        return {\n          url,\n          title: typeof entry?.title === 'string' && entry.title.length > 0 ? entry.title : url,\n          snippet,\n          publishedAt: toPublishedAt(entry?.publishedTime, entry?.publishDate, entry?.publishedAt, entry?.timestamp),\n        };\n      })\n      .filter((source): source is NonNullable<typeof source> => source !== undefined);\n\n    // Throw rather than return an empty result: an empty-but-successful return\n    // ends the fallback chain in `apply`, so an API revision that breaks the\n    // shape above would silently degrade every search to \"No results found.\"\n    // instead of moving on to the next configured provider.\n    if (sources.length === 0) throw new ProviderError('Jina search returned no parsable results.');\n\n    return { content: '', sources };\n  },\n\n  /**\n   * An empty `apiKey` is the keyless fallback at the end of the fetch chain:\n   * Reader serves anonymous requests at a lower rate limit, and an empty\n   * `Bearer` header would be rejected rather than treated as anonymous.\n   */\n  async fetch(url: string, apiKey: string, signal?: AbortSignal): Promise<FetchResult> {\n    const res = await fetch(`https://r.jina.ai/${encodeURIComponent(url)}`, {\n      method: 'GET',\n      headers: {\n        ...(apiKey ? { 'Authorization': `Bearer ${apiKey}` } : {}),\n        'Accept': 'text/plain',\n      },\n      signal,\n    });\n    assertOk(res, 'Jina fetch');\n    const text = await res.text();\n    if (text.trim() === '') throw new ProviderError('Jina fetch returned no content.');\n    // Jina Reader returns the full decoded page unless an `x-max-tokens` budget\n    // is requested, which we never set, so there is no provider-side cap to\n    // report. The official seam still flags truncation if its own\n    // `fetchMaxOutputChars` cap bites.\n    return { content: text, truncated: false };\n  },\n};\n"
    },
    {
      "path": "src/providers/tavily.ts",
      "content": "import { WebSearchProvider, SearchResult, FetchResult, SearchOptions } from '../types.js';\nimport { ProviderError, assertOk, clampCount, isParamRejection, toSnippet, toPublishedAt } from './fields.js';\n\n/**\n * Tavily's `country` takes a lower-case English country name, not an ISO code,\n * and only applies to `topic: general` — the topic this provider always uses.\n */\nconst TAVILY_COUNTRY: Record<string, string> = {\n  CN: 'china',\n  HK: 'hong kong',\n  TW: 'taiwan',\n  SG: 'singapore',\n  JP: 'japan',\n  KR: 'south korea',\n  US: 'united states',\n  GB: 'united kingdom',\n};\n\nexport const tavilyProvider: WebSearchProvider = {\n  name: 'tavily',\n  supportsFetch: true,\n  async search(query: string, apiKey: string, signal?: AbortSignal, options?: SearchOptions): Promise<SearchResult> {\n    // Tavily's `max_results` accepts 0-20; omitted keeps its default.\n    const maxResults = clampCount(options?.maxResults, 20);\n    const country = options?.region ? TAVILY_COUNTRY[options.region] : undefined;\n    const exclude = options?.excludeDomains?.slice(0, 150) ?? [];\n    const post = (withCountry: boolean) =>\n      fetch('https://api.tavily.com/search', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          api_key: apiKey,\n          query: query,\n          search_depth: options?.searchDepth === 'advanced' ? 'advanced' : 'basic',\n          include_answer: true,\n          ...(maxResults !== undefined ? { max_results: maxResults } : {}),\n          ...(options?.freshness ? { time_range: options.freshness } : {}),\n          ...(exclude.length > 0 ? { exclude_domains: exclude } : {}),\n          ...(withCountry && country ? { country } : {}),\n        }),\n        signal,\n      });\n    let res = await post(true);\n    // The country enum is documented only in part; a name it does not know\n    // must cost the region, not the whole search.\n    if (country && isParamRejection(res)) res = await post(false);\n    assertOk(res, 'Tavily search');\n    const data = await res.json();\n    const entries: any[] = Array.isArray(data?.results) ? data.results : [];\n    if (entries.length === 0) throw new ProviderError('Tavily search returned no results.');\n\n    return {\n      content: data.answer || '',\n      sources: entries.map((r: any) => ({\n        url: r.url,\n        title: r.title,\n        // Tavily's `content` is already an excerpt, but its length varies a lot\n        // between results; trimming keeps it in line with the other engines.\n        snippet: toSnippet(r.content),\n        // Tavily returns `published_date` only for `topic: 'news'`; this stays a\n        // general web search, so expect it to be absent. Read anyway — it costs\n        // nothing and lands automatically if the topic ever changes.\n        publishedAt: toPublishedAt(r.published_date)\n      }))\n    };\n  },\n\n  async fetch(url: string, apiKey: string, signal?: AbortSignal): Promise<FetchResult> {\n    const res = await fetch('https://api.tavily.com/extract', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        api_key: apiKey,\n        urls: [url],\n      }),\n      signal,\n    });\n    assertOk(res, 'Tavily extract');\n    const data = await res.json();\n    const content = data?.results?.[0]?.raw_content;\n    if (typeof content !== 'string' || content.trim() === '') {\n      // A URL Tavily could not extract lands in `failed_results`, not as an\n      // HTTP error — surface its reason so the next engine gets a turn.\n      const reason = data?.failed_results?.[0]?.error;\n      throw new ProviderError(`Tavily extract returned no content${typeof reason === 'string' ? `: ${reason}` : '.'}`);\n    }\n    // Tavily's /extract endpoint returns the full decoded `raw_content` with\n    // no documented size cap, so there is no provider-side truncation to\n    // report; the official seam still flags its own output-cap cut.\n    return { content, truncated: false };\n  }\n};\n"
    }
